edits.text:
:root {
    --bg-main: #f4f7fb;
    --bg-card: #ffffff;
    --bg-strong: #0f2f3b;
    --text-main: #1f2d3d;
    --text-muted: #556575;
    --accent: #0f8b8d;
    --accent-soft: #cdeff0;
    --danger: #c44536;
    --border: #dde4ea;
}

body[data-theme="dark"] {
    --bg-main: #132029;
    --bg-card: #1a2a34;
    --bg-strong: #0c1820;
    --text-main: #e8f0f6;
    --text-muted: #a1b5c3;
    --accent: #64d2c1;
    --accent-soft: #23454b;
    --danger: #ff6b6b;
    --border: #2a3b46;
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    font-family: "Segoe UI", Tahoma, sans-serif;
    color: var(--text-main);
    background: radial-gradient(circle at 10% 10%, #fef7dc 0%, var(--bg-main) 40%);
    min-height: 100vh;
}

#app {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.header {
    background: linear-gradient(120deg, #0f8b8d 0%, #0f2f3b 100%);
    color: #fff;
    padding: 1rem 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    position: relative;
    z-index: 1200;
}

.header h1 {
    margin: 0;
    font-size: 1.4rem;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 0.7rem;
}

