    font-weight: 600;
}

.nav-link.active,
.nav-link:hover {
    color: #06222d;
    background: #fef7dc;
}

.layout-grid {
    display: grid;
    grid-template-columns: 1fr 360px;
    gap: 1rem;
    padding: 1rem;
    flex: 1;
}

