}

.alert-success {
    background: #dcf8ea;
    color: #186446;
}

.modal {
    border: 0;
    border-radius: 12px;
    width: min(560px, 95vw);
    padding: 0;
}

.modal::backdrop {
    background: #0d1a2388;
}

.modal form {
    padding: 1rem;
    display: grid;
    gap: 0.7rem;
}

.modal label,
.modal fieldset {
    display: grid;
    gap: 0.3rem;
    margin: 0;
    border: 0;
    padding: 0;
}

.modal fieldset label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.row-inline {
    display: grid;
    grid-template-columns: 70px 1fr;
    gap: 0.5rem;
}

.row-inline-double {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

#store-inventory-form .row-inline {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.field-error {
    min-height: 1.1em;
    color: var(--danger);
    font-size: 0.78rem;
}

.modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
}

.uml-wrap {
    overflow: auto;
}

.footer {
    padding: 0.8rem;
    text-align: center;
    color: var(--text-muted);
}

@media (max-width: 1024px) {
    .layout-grid {
        grid-template-columns: 1fr;
    }

    .notifications-panel {
        position: static;
        max-height: none;
    }

    .store-map-global {
        height: 320px;
    }

    .store-3d-canvas {
        height: 300px;
    }
}

@media (max-width: 640px) {
    .header {
        flex-direction: column;
        align-items: flex-start;
    }

    .top-nav {
        overflow-x: auto;
    }

    .toolbar-actions {
        width: 100%;
    }

    .toolbar-actions input {
        width: 100%;
    }
}

