edits.text:
:root {
    --bg-main: #f3f5f7;
    --bg-card: #ffffff;
    --bg-strong: #12222c;
    --text-main: #0f1720;
    --text-muted: #52606d;
    --accent: #0b6e6e;
    --accent-soft: #e0f0f0;
    --danger: #b42318;
    --success: #15803d;
    --warning: #d97706;
    --border: #d7dee5;
    --shadow-sm: 0 6px 16px #0f17200d;
    --shadow-md: 0 10px 30px #0f17201a;
}

body[data-theme="dark"] {
    --bg-main: #0f1720;
    --bg-card: #17212a;
    --bg-strong: #0b131a;
    --text-main: #eaf0f5;
    --text-muted: #9ab0c2;
    --accent: #4ec5bc;
    --accent-soft: #17353a;
    --danger: #ff766d;
    --success: #3fbc72;
    --warning: #f2a53a;
    --border: #273643;
    --shadow-sm: 0 8px 18px #00000033;
    --shadow-md: 0 14px 34px #0000004a;
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    font-family: "Aptos", "Segoe UI Variable", "Trebuchet MS", "Gill Sans", "Noto Sans", sans-serif;
    color: var(--text-main);
    background:
        radial-gradient(circle at 12% -8%, #c7edf0 0%, transparent 40%),
        radial-gradient(circle at 92% 12%, #f6e5c9 0%, transparent 36%),
        var(--bg-main);
    min-height: 100vh;
}

#app {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.header {
    background: linear-gradient(120deg, #0b6e6e 0%, #12222c 100%);
    color: #fff;
    padding: 1rem 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    position: relative;
    z-index: 1200;
}

.header h1 {
    margin: 0;
    font-size: 1.42rem;
    letter-spacing: 0.02em;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 0.7rem;
}

.top-nav {
    position: sticky;
    top: 0;
    z-index: 1300;
    background: #12222ce0;
    backdrop-filter: blur(8px);
    padding: 0.6rem 1rem;
    display: flex;
    gap: 0.5rem;
    border-bottom: 1px solid #00000030;
}

.nav-link {
    color: #dce9ef;
    text-decoration: none;
    padding: 0.4rem 0.8rem;
    border-radius: 999px;
    transition: 0.2s ease;
    font-weight: 600;
}

.nav-link.active,
.nav-link:hover {
    color: #06202a;
    background: #f5eee1;
}

.layout-grid {
    display: grid;
    grid-template-columns: 1fr 360px;
    gap: 1rem;
    padding: 1rem;
    flex: 1;
}

.main-area {
    min-width: 0;
}

.view {
    display: none;
}

.active-view {
    display: block;
}

.panel {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 1rem;
    margin-top: 1rem;
    box-shadow: var(--shadow-sm);
    animation: panel-in 0.3s ease both;
}

.stats-panel {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 0.8rem;
}

.stat-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 0.8rem;
    box-shadow: var(--shadow-sm);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.stat-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.stat-label {
    display: block;
    color: var(--text-muted);
    font-size: 0.8rem;
}

.stat-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: var(--accent);
}

.toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    flex-wrap: wrap;
}

.toolbar-actions {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

input,
select,
button {
    font: inherit;
}

input[type="search"],
input[type="text"],
input[type="email"],
input[type="url"],
input[type="date"],
input[type="number"],
input[type="password"],
select {
    padding: 0.55rem 0.65rem;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--bg-card);
    color: var(--text-main);
}

input:focus-visible,
select:focus-visible,
button:focus-visible,
.nav-link:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--accent) 70%, white 30%);
    outline-offset: 2px;
}

.primary-btn,
.secondary-btn,
.chip-btn,
.filter-btn {
    border: 0;
    border-radius: 8px;
    padding: 0.5rem 0.8rem;
    cursor: pointer;
    transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.primary-btn {
    background: var(--accent);
    color: #fff;
    font-weight: 600;
    box-shadow: 0 4px 10px #0b6e6e33;
}

.primary-btn:hover {
    background: #095959;
    transform: translateY(-1px);
}

.secondary-btn,
.chip-btn {
    background: var(--accent-soft);
    color: var(--text-main);
}

.secondary-btn:hover,
.chip-btn:hover,
.filter-btn:hover {
    transform: translateY(-1px);
    box-shadow: var(--shadow-sm);
}

.chip-btn.danger {
    background: #f8d9d4;
    color: #8a2619;
}

.connection-status {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.7rem;
    border-radius: 999px;
    background: #ffffff1a;
}

.status-icon {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.status-icon.connected {
    background: #7bec6f;
}

.status-icon.disconnected {
    background: #ff7a7a;
}

.notifications-panel {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 1rem;
    height: fit-content;
    max-height: calc(100vh - 110px);
    overflow: auto;
    position: sticky;
    top: 70px;
    box-shadow: var(--shadow-sm);
}

.mini-stats {
    display: grid;
    gap: 0.25rem;
    margin-bottom: 0.8rem;
    color: var(--text-muted);
    font-size: 0.9rem;
}

.filter-controls {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.4rem;
    margin-bottom: 0.8rem;
}

.filter-btn {
    background: #edf1f7;
    color: #2f4553;
}

.filter-btn.active {
    background: var(--accent);
    color: #fff;
}

.filter-btn.clear-btn {
    background: #ffe3de;
    color: #8a2619;
}

.notifications-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.notification-item {
    background: #f9fcff;
    border: 1px solid var(--border);
    border-left: 4px solid #9cb2c2;
    border-radius: 8px;
    padding: 0.6rem;
}

.notification-item.price {
    border-left-color: #d89a00;
}

.notification-item.stock {
    border-left-color: #c44536;
}

.notification-header {
    display: flex;
    justify-content: space-between;
    gap: 1rem;
    font-size: 0.85rem;
}

.notification-title {
    font-weight: 700;
}

.notification-time {
    color: var(--text-muted);
}

.debug-panel {
    margin-top: 0.8rem;
    border-top: 1px dashed var(--border);
    padding-top: 0.6rem;
    font-size: 0.85rem;
}

.table-wrap {
    width: 100%;
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th,
td {
    border-bottom: 1px solid var(--border);
    text-align: left;
    padding: 0.62rem;
    vertical-align: top;
}

th {
    color: var(--text-muted);
    font-size: 0.85rem;
    background: color-mix(in srgb, var(--bg-card) 86%, #e9f0f6 14%);
    position: sticky;
    top: 0;
    z-index: 2;
}

tbody tr {
    transition: background-color 0.18s ease;
}

tbody tr:hover {
    background: color-mix(in srgb, var(--accent-soft) 58%, var(--bg-card) 42%);
}

.thumb,
.avatar {
    width: 42px;
    height: 42px;
    object-fit: cover;
    border-radius: 8px;
    border: 1px solid var(--border);
}

.avatar {
    border-radius: 50%;
}

.employee-photo,
.store-photo {
    transition: transform 0.45s ease, box-shadow 0.45s ease;
    transform-origin: center center;
}

.employee-photo:hover {
    transform: scale(1.22);
    box-shadow: 0 8px 18px #0f2f3b2b;
}

.store-photo:hover {
    transform: scale(1.16) rotate(360deg);
    box-shadow: 0 10px 22px #0f2f3b2b;
}

.category-chip,
.country-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.2rem 0.45rem;
    border-radius: 999px;
    background: #eef5fb;
    color: #2f4553;
    font-size: 0.82rem;
    white-space: nowrap;
}

.category-chip i,
