    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
}

.uml-wrap {
    overflow: auto;
}

.footer {
    padding: 0.8rem;
    text-align: center;
    color: var(--text-muted);
}

@keyframes panel-in {
    from {
