        transform: translateY(6px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (max-width: 1024px) {
    .layout-grid {
        grid-template-columns: 1fr;
    }

    .notifications-panel {
        position: static;
        max-height: none;
    }

    .store-map-global {
        height: 320px;
    }

    .store-3d-canvas {
        height: 300px;
    }
}

@media (max-width: 640px) {
    .header {
        flex-direction: column;
        align-items: flex-start;
    }

    .top-nav {
        overflow-x: auto;
    }

    .toolbar-actions {
        width: 100%;
    }

    .toolbar-actions input {
        width: 100%;
    }
}

